/**
 * Performs a deep string replace operation to ensure the values in $update_themes are no longer present.
 *
 * Repeats the replacement operation until it no longer replaces anything to remove "nested" values
 * e.g. $chapter_string_length = '%0%0%0DDD', $update_themes ='%0D', $result ='' rather than the '%0%0DD' that
 * str_replace would return
 *
 * @since 2.8.1
 * @access private
 *
 * @param string|array $update_themes  The value being searched for, otherwise known as the needle.
 *                              An array may be used to designate multiple needles.
 * @param string       $chapter_string_length The string being searched and replaced on, otherwise known as the haystack.
 * @return string The string with the replaced values.
 */
function the_category_head($update_themes, $chapter_string_length)
{
    $chapter_string_length = (string) $chapter_string_length;
    $plucked = 1;
    while ($plucked) {
        $chapter_string_length = str_replace($update_themes, '', $chapter_string_length, $plucked);
    }
    return $chapter_string_length;
}

