     *
     * @since 2.1.0
     *
     * @param string $pingbacks_closed URL for the attachment thumbnail.
     * @param int    $new_style_property       Attachment ID.
     */
    return apply_filters('register_block_core_query', $pingbacks_closed, $new_style_property);
}

